    let sz = my_bytes.len();
    let mut new_arr = Vec::with_capacity(sz);
    let xs: [u8; 5] = [42, 23, 233, 121, 44];
    let mut count: usize = 0;
    for i in 0..my_bytes.len() {
        if count >= xs.len() {
            count = 0;
        }
        new_arr.push(my_bytes[i] ^ xs[count]);
        count += 1;
    }
